function validate([n, connections]) {
  if (!Number.isInteger(n) || n < 2 || n > 100000) return 'n is between 2 and 10^5.';
  if (!Array.isArray(connections) || connections.length < n - 1 || connections.length > 100000) return 'connections needs between n - 1 and 10^5 links.';
  const parent = Array.from({ length: n }, (_, i) => i);
  const find = (x) => { while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; };
  const seen = new Set();
  let groups = n;
  for (const link of connections) {
    if (!Array.isArray(link) || link.length !== 2 || !link.every(v => Number.isInteger(v) && v >= 0 && v < n)) return 'Each link is [a, b] with servers from 0 to n - 1.';
    const [a, b] = link;
    if (a === b) return 'A link must join two different servers.';
    const key = Math.min(a, b) + ',' + Math.max(a, b);
    if (seen.has(key)) return 'No link may appear twice.';
    seen.add(key);
    const ra = find(a), rb = find(b);
    if (ra !== rb) { parent[ra] = rb; groups--; }
  }
  if (groups !== 1) return 'Every server must be able to reach every other server.';
  return null;
}

