function criticalConnections(n, connections) {
  // Remove each link in turn and test whether a breadth-first search still reaches every server.
  const result = [];
  for (let skip = 0; skip < connections.length; skip++) {
    const adjacency = Array.from({ length: n }, () => []);
    connections.forEach(([a, b], index) => {
      if (index !== skip) { adjacency[a].push(b); adjacency[b].push(a); }
    });
    const reached = new Set([0]);
    const queue = [0];
    while (queue.length) {
      const server = queue.shift();
      for (const other of adjacency[server]) if (!reached.has(other)) { reached.add(other); queue.push(other); }
    }
    if (reached.size < n) result.push(connections[skip].slice());
  }
  return result;
}

