function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? int(700, 1000) : int(2, 8);
  const seen = new Set();
  const pairs = [];
  const add = (a, b) => {
    const key = a < b ? a + ',' + b : b + ',' + a;
    if (a === b || seen.has(key)) return;
    seen.add(key);
    pairs.push([a, b]);
  };
  // A spanning tree keeps the network connected; a short reach makes long chains, a long reach makes bushy trees.
  const reach = [1, 3, 50, n][int(0, 3)];
  for (let i = 1; i < n; i++) add(i, i - int(1, Math.min(i, reach)));
  // Extra links close cycles; links between nearby servers leave some bridges in place.
  const extra = large ? int(0, Math.min(2000 - (n - 1), n)) : int(0, n);
  const window = rand() < 0.7 ? int(2, 5) : n;
  for (let t = 0; t < extra; t++) {
    const a = int(0, n - 1);
    add(a, Math.max(0, Math.min(n - 1, a + int(-window, window))));
  }
  // Hide the construction: relabel servers, shuffle the links and flip their ends at random.
  const label = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) { const j = int(0, i); [label[i], label[j]] = [label[j], label[i]]; }
  for (let i = pairs.length - 1; i > 0; i--) { const j = int(0, i); [pairs[i], pairs[j]] = [pairs[j], pairs[i]]; }
  const connections = pairs.map(([a, b]) => rand() < 0.5 ? [label[a], label[b]] : [label[b], label[a]]);
  return [n, connections];
}
